import { useMemo, useState } from 'react'
import {
  Activity, AlertTriangle, ArrowRight, BarChart3, Bot, Building2, CalendarDays, Check,
  CheckCircle2, ChevronRight, Clock, CreditCard, Crown, Download, Fingerprint, Gift,
  Dumbbell, HeartPulse, KeyRound, LayoutDashboard, Lock, MapPin, MessageCircle, Plus, QrCode, RefreshCw,
  Send, Settings as SettingsIcon, ShieldCheck, Sparkles, Star, Target, TrendingUp, Trophy, Upload, UserCog,
  Users, Wallet, Watch, X, Zap,
} from 'lucide-react'
import { roleLabels, useApp } from '../lib/app-context'
import { useActions } from '../lib/actions'
import {
  attendanceTrend, branchPerformance, churnRiskScore, dashboardMetrics, expenseCategoryBreakdown,
  peakHourData, planDistribution,
} from '../lib/analytics'
import { downloadFile, formatCurrency, formatDate, isoDate, titleCase, toCsv, uid } from '../lib/utils'
import type { ModuleKey, Role } from '../types'
import { BranchBarChart, FinanceBarChart, MemberGrowthChart, PeakHoursChart, ProgressLineChart, RevenueAreaChart, PlanDonutChart } from '../components/charts'
import { Avatar, Badge, Button, Card, CardHeader, DataTable, Modal, PageHeader, ProgressBar, StatCard, StatusBadge, Tabs, Toggle } from '../components/ui'

/* -------------------------------- Reports -------------------------------- */

export function Reports() {
  const { db, branchId } = useApp()
  const [tab, setTab] = useState('financial')
  const currency = db.settings.currency
  const metrics = useMemo(() => dashboardMetrics(db, branchId), [db, branchId])
  const branches = useMemo(() => branchPerformance(db), [db])
  const peak = useMemo(() => peakHourData(metrics.attendance), [metrics.attendance])
  const trend = useMemo(() => attendanceTrend(metrics.attendance, 14), [metrics.attendance])
  const expenses = expenseCategoryBreakdown(db, branchId)
  const plans = planDistribution(db, branchId)
  const last = db.monthlyRevenue.at(-1) || { revenue: 0, expenses: 0, target: 1 }
  const yearlyRevenue = db.monthlyRevenue.reduce((s, m) => s + m.revenue, 0)
  const yearlyExpenses = db.monthlyRevenue.reduce((s, m) => s + m.expenses, 0)
  const retention = metrics.retention
  const churn = Math.max(0, 100 - retention)
  const clv = Math.round(metrics.totalRevenue / Math.max(1, metrics.members.length) * 2.4)

  function exportAll() {
    downloadFile('gymzard-business-report.csv', toCsv(db.monthlyRevenue.map((m) => ({ Month: m.month, Revenue: m.revenue, Expenses: m.expenses, Target: m.target, Profit: m.revenue - m.expenses }))), 'text/csv;charset=utf-8')
  }

  const tabs = [
    { id: 'financial', label: 'Financial' },
    { id: 'members', label: 'Members' },
    { id: 'attendance', label: 'Attendance' },
    { id: 'analytics', label: 'Business analytics' },
  ]

  return (
    <div className="space-y-6">
      <PageHeader eyebrow="Reports & analytics" title="Business intelligence" subtitle="Financial, member, attendance, and growth analytics across your entire gym operation." actions={<><Button variant="outline" icon={Download} onClick={exportAll}>Export report</Button><Button icon={RefreshCw} onClick={() => window.location.reload()}>Refresh data</Button></>} />
      <Tabs items={tabs} value={tab} onChange={setTab} className="rounded-t-2xl border border-blue-100 bg-white px-2" />
      {tab === 'financial' ? <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard title="Daily revenue" value={formatCurrency(metrics.todayCollection, currency, true)} icon={Wallet} tone="green" /><StatCard title="Monthly revenue" value={formatCurrency(metrics.monthlyRevenue, currency, true)} icon={TrendingUp} /><StatCard title="Yearly revenue" value={formatCurrency(yearlyRevenue, currency, true)} icon={BarChart3} tone="blue" /><StatCard title="Monthly profit" value={formatCurrency(metrics.profit, currency, true)} icon={CreditCard} tone="purple" /><StatCard title="Pending payments" value={formatCurrency(metrics.pendingDues, currency, true)} icon={AlertTriangle} tone="amber" /></div><div className="grid gap-5 xl:grid-cols-[1.7fr_1fr]"><Card><CardHeader title="Revenue, expenses & targets" subtitle="12-month financial performance" /><div className="px-2 py-4 sm:px-4"><RevenueAreaChart data={db.monthlyRevenue} currency={currency} /></div></Card><Card><CardHeader title="Expense breakdown" subtitle="Spend by category" /><div className="px-2 py-4"><FinanceBarChart data={expenses} currency={currency} /></div></Card></div><div className="grid gap-5 xl:grid-cols-2"><Card><CardHeader title="Profit & loss statement" subtitle="Trailing 12 months" /><div className="space-y-3 p-5"><ReportRow label="Gross revenue" value={formatCurrency(yearlyRevenue, currency)} tone="green" /><ReportRow label="Total expenses" value={`− ${formatCurrency(yearlyExpenses, currency)}`} tone="red" /><ReportRow label="Gross profit" value={formatCurrency(yearlyRevenue - yearlyExpenses, currency)} tone="blue" /><ReportRow label="Profit margin" value={`${Math.round((yearlyRevenue - yearlyExpenses) / Math.max(1, yearlyRevenue) * 100)}%`} tone="purple" /><ReportRow label="Outstanding dues" value={formatCurrency(metrics.pendingDues, currency)} tone="amber" /><ReportRow label="Trainer commissions" value={formatCurrency(db.trainers.reduce((s, t) => s + t.sessions * 1500 * t.commissionRate / 100, 0), currency, true)} tone="cyan" /></div></Card><Card><CardHeader title="Branch revenue vs target" subtitle="Performance by location" /><div className="px-2 py-4 sm:px-4"><BranchBarChart data={branches} currency={currency} /></div><div className="border-t border-blue-50 p-4"><ReportRow label="Revenue target attainment" value={`${Math.round(last.revenue / last.target * 100)}%`} tone="green" /><ReportRow label="Projected next month" value={formatCurrency(last.revenue * 1.08, currency, true)} tone="blue" /></div></Card></div></div> : null}
      {tab === 'members' ? <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard title="Total members" value={metrics.members.length} icon={Users} /><StatCard title="Active members" value={metrics.activeMembers} icon={CheckCircle2} tone="green" /><StatCard title="Expired members" value={metrics.expiredMembers} icon={AlertTriangle} tone="red" /><StatCard title="New registrations" value={metrics.newThisMonth} icon={Plus} tone="cyan" /><StatCard title="Retention rate" value={`${retention}%`} icon={Target} tone="purple" /></div><div className="grid gap-5 xl:grid-cols-[1.5fr_1fr]"><Card><CardHeader title="Member growth" subtitle="Registrations and renewals" /><div className="px-2 py-4 sm:px-4"><MemberGrowthChart data={db.memberGrowth} /></div></Card><Card><CardHeader title="Membership distribution" subtitle="Members by plan category" /><div className="px-2 py-3"><PlanDonutChart data={plans} /></div></Card></div><div className="grid gap-5 xl:grid-cols-3"><Card><CardHeader title="Member status" /><div className="space-y-3 p-5">{['Active', 'Trial', 'Expired', 'Frozen', 'Inactive'].map((s, i) => { const count = metrics.members.filter((m) => m.status === s).length; return <div key={s}><div className="flex justify-between text-xs font-semibold text-slate-600"><span>{s}</span><span>{count}</span></div><ProgressBar className="mt-1.5" value={count} max={metrics.members.length} tone={(['green', 'cyan', 'red', 'purple', 'amber'] as const)[i]} /></div> })}</div></Card><Card><CardHeader title="Retention & renewals" /><div className="space-y-3 p-5"><ReportRow label="Retention rate" value={`${retention}%`} tone="green" /><ReportRow label="Cancellation rate" value={`${Math.round(metrics.members.filter((m) => m.status === 'Inactive').length / Math.max(1, metrics.members.length) * 100)}%`} tone="red" /><ReportRow label="Renewals this month" value={db.memberGrowth.at(-1)?.renewals || 0} tone="blue" /><ReportRow label="Expiring in 7 days" value={metrics.expiringSoon.length} tone="amber" /><ReportRow label="Inactive members" value={metrics.inactiveMembers} tone="purple" /></div></Card><Card><CardHeader title="Churn risk watchlist" subtitle="Members least likely to renew" /><div className="space-y-2 p-4">{[...metrics.members].sort((a, b) => churnRiskScore(b) - churnRiskScore(a)).slice(0, 6).map((m) => <div key={m.id} className="flex items-center gap-2 rounded-xl border border-blue-50 p-2.5"><Avatar name={m.name} size="xs" /><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold text-slate-700">{m.name}</p><p className="text-[10px] text-slate-400">Expires {formatDate(m.expiresAt)}</p></div><Badge tone={churnRiskScore(m) > 70 ? 'red' : 'amber'}>{churnRiskScore(m)}%</Badge></div>)}</div></Card></div></div> : null}
      {tab === 'attendance' ? <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard title="Daily attendance" value={metrics.todayAttendance} icon={QrCode} /><StatCard title="Average daily" value={Math.round(metrics.attendance.length / 30)} icon={Activity} tone="cyan" /><StatCard title="Peak hour" value={peak.reduce((a, b) => a.visits > b.visits ? a : b).hour} icon={Clock} tone="amber" /><StatCard title="Inside now" value={metrics.insideNow} icon={Users} tone="green" /><StatCard title="30-day check-ins" value={metrics.attendance.length} icon={TrendingUp} tone="purple" /></div><div className="grid gap-5 xl:grid-cols-2"><Card><CardHeader title="Peak gym hours" subtitle="Historical check-ins by hour" /><div className="px-2 py-4 sm:px-4"><PeakHoursChart data={peak} /></div></Card><Card><CardHeader title="Attendance trend" subtitle="Daily visits over the last 14 days" /><div className="px-2 py-4 sm:px-4"><ProgressLineChart data={trend} dataKeys={[{ key: 'visits', name: 'Visits', color: '#1557d6' }]} /></div></Card></div><Card><CardHeader title="Attendance leaderboard" subtitle="Most and least active members" /><div className="grid gap-4 p-4 md:grid-cols-2"><div><p className="mb-2 text-xs font-bold text-brand-950">Most active</p>{[...metrics.members].sort((a, b) => b.attendanceCount - a.attendanceCount).slice(0, 5).map((m) => <LeaderRow key={m.id} name={m.name} value={`${m.attendanceCount} visits`} />)}</div><div><p className="mb-2 text-xs font-bold text-brand-950">Least active</p>{[...metrics.members].sort((a, b) => a.attendanceCount - b.attendanceCount).slice(0, 5).map((m) => <LeaderRow key={m.id} name={m.name} value={`${m.attendanceCount} visits`} tone="amber" />)}</div></div></Card></div> : null}
      {tab === 'analytics' ? <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard title="MRR" value={formatCurrency(metrics.mrr, currency, true)} icon={Wallet} tone="green" /><StatCard title="Customer lifetime value" value={formatCurrency(clv, currency, true)} icon={Crown} tone="purple" /><StatCard title="Churn rate" value={`${churn}%`} icon={AlertTriangle} tone="red" /><StatCard title="Revenue / member" value={formatCurrency(metrics.arpm, currency, true)} icon={CreditCard} tone="blue" /><StatCard title="Conversion rate" value={`${Math.round(db.leads.filter((l) => l.status === 'Converted').length / Math.max(1, db.leads.length) * 100)}%`} icon={Target} tone="amber" /></div><div className="grid gap-5 xl:grid-cols-[1.6fr_1fr]"><Card><CardHeader title="Growth trends" subtitle="Revenue and member growth correlation" /><div className="px-2 py-4 sm:px-4"><RevenueAreaChart data={db.monthlyRevenue} currency={currency} /></div></Card><Card><CardHeader title="Key growth indicators" subtitle="Demo business analytics" /><div className="space-y-3 p-5"><ReportRow label="MRR growth" value="+12.4%" tone="green" /><ReportRow label="Revenue per member" value={formatCurrency(metrics.arpm, currency)} tone="blue" /><ReportRow label="CLV / CAC ratio" value="4.8×" tone="purple" /><ReportRow label="Member growth YoY" value="+38%" tone="cyan" /><ReportRow label="Avg. membership length" value="7.2 months" tone="amber" /><ReportRow label="Referral share" value="18%" tone="green" /></div></Card></div><div className="grid gap-5 xl:grid-cols-3"><Card><CardHeader title="Revenue forecast" subtitle="Next 3 months (demo projection)" /><div className="space-y-3 p-5">{['Nov', 'Dec', 'Jan'].map((m, i) => <div key={m}><div className="flex justify-between text-xs font-semibold text-slate-600"><span>{m}</span><span>{formatCurrency(last.revenue * (1 + (i + 1) * .08), currency, true)}</span></div><ProgressBar className="mt-1.5" value={70 + i * 10} tone="blue" /></div>)}</div></Card><Card><CardHeader title="Revenue health" subtitle="Quality of recurring income" /><div className="space-y-3 p-5"><ReportRow label="Recurring revenue share" value="72%" tone="green" /><ReportRow label="Auto-renew coverage" value={`${Math.round(metrics.members.filter((m) => m.autoRenew).length / Math.max(1, metrics.members.length) * 100)}%`} tone="blue" /><ReportRow label="Collection efficiency" value="91%" tone="purple" /><ReportRow label="Outstanding ratio" value={`${Math.round(metrics.pendingDues / Math.max(1, metrics.monthlyRevenue) * 100)}%`} tone="amber" /></div></Card><Card><CardHeader title="Opportunity summary" subtitle="Recommended next actions" /><div className="space-y-3 p-5">{[{ icon: AlertTriangle, text: `${metrics.expiringSoon.length} memberships expire this week — launch a renewal campaign.` }, { icon: Users, text: `${metrics.inactiveMembers} inactive members could be re-engaged with a comeback offer.` }, { icon: CreditCard, text: `${formatCurrency(metrics.pendingDues, currency)} in dues is waiting to be collected.` }, { icon: TrendingUp, text: 'Evening classes are near capacity — consider adding a second batch.' }].map((o, i) => <div key={i} className="flex gap-3 rounded-xl border border-blue-50 p-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-brand-50 text-brand-600"><o.icon className="h-4 w-4" /></span><p className="text-xs leading-relaxed text-slate-600">{o.text}</p></div>)}</div></Card></div></div> : null}
    </div>
  )
}

/* -------------------------------- Branches ------------------------------- */

export function Branches() {
  const { db, branchId, setBranchId, toast } = useApp()
  const actions = useActions()
  const [selected, setSelected] = useState<string | null>(null)
  const performance = useMemo(() => branchPerformance(db), [db])
  const branch = db.branches.find((b) => b.id === selected)
  const totalMembers = performance.reduce((s, b) => s + b.members, 0)
  const totalRevenue = performance.reduce((s, b) => s + b.revenue, 0)
  const onTarget = performance.filter((b) => b.revenue >= b.target * .8).length

  return (
    <div className="space-y-6">
      <PageHeader eyebrow="Multi-branch management" title="Branches" subtitle="Branch-specific dashboards, centralized member data, staff, revenue, attendance, and transfers." actions={<><Button variant="outline" icon={Users} onClick={() => actions.openTransferForm(db.members[0])}>Transfer member</Button><Button icon={Plus} onClick={() => actions.openBranchForm()}>Add branch</Button></>} />
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard title="Gym branches" value={db.branches.length} icon={Building2} hint="active locations" /><StatCard title="Total members" value={totalMembers} icon={Users} tone="green" hint="all branches" /><StatCard title="Active members" value={performance.reduce((s, b) => s + b.active, 0)} icon={CheckCircle2} tone="cyan" hint="currently valid" /><StatCard title="Combined revenue" value={formatCurrency(totalRevenue, db.settings.currency, true)} icon={Wallet} tone="blue" hint="all-time demo" /><StatCard title="Near target" value={onTarget} icon={Target} tone="purple" hint="branches ≥80%" /></div>
      <div className="grid gap-4 lg:grid-cols-2 xl:grid-cols-3">{db.branches.map((b) => { const p = performance.find((x) => x.id === b.id)!; const staff = db.staff.filter((s) => s.branchId === b.id).length + db.trainers.filter((t) => t.branchId === b.id).length; return <Card key={b.id} className="overflow-hidden"><div className="h-1.5" style={{ background: b.color }} /><div className="p-5"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-wide text-brand-500">{b.code}</p><h3 className="mt-1 text-lg font-extrabold text-brand-950">{b.name}</h3><p className="mt-1 flex items-center gap-1 text-xs text-slate-400"><MapPin className="h-3.5 w-3.5" />{b.address}, {b.city}</p></div><StatusBadge status={b.status} /></div><div className="mt-4 grid grid-cols-2 gap-2"><Mini label="Members" value={p.members} /><Mini label="Active" value={p.active} /><Mini label="Revenue" value={formatCurrency(p.revenue, db.settings.currency, true)} /><Mini label="Attendance" value={p.attendance} /></div><div className="mt-4"><div className="flex justify-between text-xs font-semibold text-slate-500"><span>Monthly target</span><span>{Math.round(p.revenue / p.target * 100)}%</span></div><ProgressBar className="mt-1.5" value={p.revenue} max={p.target} tone={p.revenue >= p.target * .8 ? 'green' : 'amber'} /></div><div className="mt-4 flex items-center justify-between border-t border-blue-50 pt-4"><div className="flex items-center gap-2"><Avatar name={p.manager} size="sm" /><div><p className="text-[11px] text-slate-400">Manager</p><p className="text-xs font-bold text-slate-700">{p.manager}</p></div></div><span className="text-[11px] text-slate-400">{staff} staff</span></div><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" onClick={() => setSelected(b.id)}>View details</Button><Button size="sm" variant="outline" onClick={() => { setBranchId(b.id); toast(`Workspace filtered to ${b.name}`, 'info') }}>Focus branch</Button><Button size="sm" variant="ghost" onClick={() => actions.openBranchForm(b)}>Edit</Button></div></div></Card> })}</div>
      <div className="grid gap-5 xl:grid-cols-[1.4fr_1fr]"><Card><CardHeader title="Branch comparison" subtitle="Revenue, members, attendance, and outstanding dues" /><DataTable rows={performance} rowKey={(b) => b.id} columns={[
        { key: 'name', header: 'Branch', render: (b) => <div><p className="font-bold text-slate-700">{b.name}</p><p className="text-[11px] text-slate-400">{b.code} · {b.manager}</p></div> },
        { key: 'members', header: 'Members', render: (b) => <span className="text-xs text-slate-600">{b.members}</span> },
        { key: 'revenue', header: 'Revenue', render: (b) => <span className="text-xs font-bold text-brand-700">{formatCurrency(b.revenue, db.settings.currency, true)}</span> },
        { key: 'target', header: 'Target', render: (b) => <div className="w-24"><ProgressBar value={b.revenue} max={b.target} tone={b.revenue >= b.target * .8 ? 'green' : 'amber'} /></div> },
        { key: 'attendance', header: 'Attendance', render: (b) => <span className="text-xs text-slate-500">{b.attendance}</span> },
        { key: 'dues', header: 'Dues', render: (b) => <span className="text-xs font-semibold text-amber-600">{formatCurrency(b.dues, db.settings.currency, true)}</span> },
      ]} /></Card><Card><CardHeader title="Revenue by branch" subtitle="Demo revenue comparison" /><div className="px-2 py-4 sm:px-4"><BranchBarChart data={performance} currency={db.settings.currency} /></div></Card></div>
      <Card><CardHeader title="Branch-specific settings" subtitle="Pricing, transfers, staff, and centralized operations" /><div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-4"><Feature icon={CreditCard} title="Branch pricing" detail={`${db.plans.filter((p) => p.branchId !== 'all').length} branch-exclusive plans configured.`} action="Manage plans" onClick={() => toast('Branch pricing settings opened', 'info')} /><Feature icon={Users} title="Member transfers" detail="Move members between branches without losing history." action="Transfer member" onClick={() => actions.openTransferForm(db.members[0])} /><Feature icon={UserCog} title="Staff assignments" detail="Assign managers, trainers, and front-desk staff by branch." action="Open staff" onClick={() => toast('Staff branch assignments opened', 'info')} /><Feature icon={BarChart3} title="Central analytics" detail="Organization-wide reporting with branch-level drill-down." action="View reports" onClick={() => toast('Central analytics are shown above', 'info')} /></div></Card>
      <Modal open={!!branch} onClose={() => setSelected(null)} title={branch?.name || ''} subtitle={branch?.code} size="lg">{branch ? <div className="space-y-5"><div className="blue-gradient rounded-2xl p-5 text-white"><div className="flex items-start justify-between"><div><h3 className="text-xl font-extrabold">{branch.name}</h3><p className="mt-1 text-xs text-blue-100">{branch.address}, {branch.city}</p></div><Badge tone="blue" className="!bg-white/15 !text-white !ring-white/20">{branch.status}</Badge></div><div className="mt-5 grid grid-cols-3 gap-2 text-center"><Hero label="Members" value={performance.find((p) => p.id === branch.id)?.members || 0} /><Hero label="Staff" value={db.staff.filter((s) => s.branchId === branch.id).length + db.trainers.filter((t) => t.branchId === branch.id).length} /><Hero label="Opened" value={formatDate(branch.openedAt, { month: 'short', year: 'numeric' })} /></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Mini label="Manager" value={branch.manager} /><Mini label="Phone" value={branch.phone} /><Mini label="Monthly target" value={formatCurrency(branch.monthlyTarget, db.settings.currency, true)} /><Mini label="Attendance" value={performance.find((p) => p.id === branch.id)?.attendance || 0} /></div><div><p className="text-sm font-bold text-brand-950">Branch members</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{db.members.filter((m) => m.branchId === branch.id).slice(0, 8).map((m) => <div key={m.id} className="flex items-center gap-2 rounded-xl border border-blue-50 p-2.5"><Avatar name={m.name} src={m.photo} size="xs" /><span className="min-w-0 flex-1 truncate text-xs font-semibold text-slate-700">{m.name}</span><StatusBadge status={m.status} /></div>)}</div></div><div className="flex flex-wrap gap-2 border-t border-blue-50 pt-4"><Button onClick={() => { setBranchId(branch.id); setSelected(null); toast(`Workspace filtered to ${branch.name}`, 'info') }}>Open branch workspace</Button><Button variant="outline" onClick={() => actions.openBranchForm(branch)}>Edit branch</Button></div></div> : null}</Modal>
    </div>
  )
}

/* ---------------------------- Roles & access ---------------------------- */

const permissionModules: { key: ModuleKey; label: string }[] = [
  { key: 'dashboard', label: 'Dashboard' }, { key: 'members', label: 'Members' }, { key: 'memberships', label: 'Memberships' },
  { key: 'payments', label: 'Payments' }, { key: 'attendance', label: 'Attendance' }, { key: 'trainers', label: 'Trainers' },
  { key: 'workout', label: 'Workouts' }, { key: 'diet', label: 'Diet plans' }, { key: 'progress', label: 'Progress' },
  { key: 'staff', label: 'Staff & HR' }, { key: 'classes', label: 'Classes' }, { key: 'reports', label: 'Reports' },
  { key: 'branches', label: 'Branches' }, { key: 'settings', label: 'Settings' },
]
const rolePermissions: Record<Role, ModuleKey[] | 'all'> = {
  super_admin: 'all', owner: 'all',
  manager: ['dashboard', 'members', 'memberships', 'payments', 'attendance', 'trainers', 'staff', 'classes', 'reports', 'branches'],
  trainer: ['dashboard', 'members', 'attendance', 'trainers', 'workout', 'diet', 'progress', 'classes'],
  receptionist: ['dashboard', 'members', 'memberships', 'payments', 'attendance', 'classes'],
  member: [],
}

